int main(void) {
    for (int i = 1; i <= 100; i++) {
        int div3 = (i % 3 == 0);
        int div5 = (i % 5 == 0);
        if (div3 && div5) {
            for (int j = 1; j < i; j++) printf(" ");
            fputs("fizz buzz\n", stdout);
        } else if (div3) {
            for (int j = 1; j < i; j++) printf(" ");
            printf("fizz\n");
        } else if (div5) {
            for (int j = 1; j < i; j++) printf(" ");
            printf("buzz\n");
        } else {
            char buf[8];
            sprintf(buf, "%d", i);
            int w = 0;
            for (int j = 0; buf[j]; j++) w++;
            for (int j = 1; j < i - w; j++) printf(" ");
            printf("%d\n", i);
        }
    }
    return 0;
}

